$("#contactForm").validator().on("submit", function (event) {
    const english = window.location.href.indexOf('/en/', 0) > 0;
    if (event.isDefaultPrevented()) {
        // handle the invalid form...
        formError();
        console.log(window.location.href);
        console.log();
        if (english) {
            submitMSG(false, "Please complete the missing fields");
        } else {
            submitMSG(false, "Por favor complete los campos faltantes");
        }
    } else {
        // everything looks good!
        event.preventDefault();
        submitForm(english);
    }
});


function submitForm(english){
    var url = english ? "../assets/php/form-process.php" : "assets/php/form-process.php";

    var $boton = $("#form-submit");
    $boton.prop("disabled", true);

    $.ajax({
        type: "POST",
        url: url,
        // Como objeto: jQuery se encarga del url-encoding. Concatenando a mano,
        // un "&", "+" o "#" dentro del mensaje partía el payload.
        data: {
            name: $("#name").val(),
            email: $("#email").val(),
            msg_subject: $("#msg_subject").val(),
            message: $("#message").val(),
            website: $("#website").val(),   // honeypot: siempre vacío si es humano
            lang: english ? "en" : "es"
        },
        success: function (text) {
            if (text == "success") {
                formSuccess(english);
            } else {
                formError();
                submitMSG(false, text);
            }
        },
        // Sin esto, cualquier respuesta 4xx/5xx no mostraba nada: el formulario
        // quedaba mudo y el visitante no sabía si se había enviado.
        error: function (jqXHR) {
            formError();
            var msg = (jqXHR.responseText || "").trim();
            if (!msg) {
                msg = english
                    ? "We could not send your message. Please write to info@adhentux.com."
                    : "No pudimos enviar tu mensaje. Escribinos a info@adhentux.com.";
            }
            submitMSG(false, msg);
        },
        complete: function () {
            $boton.prop("disabled", false);
        }
    });
}

function formSuccess(english){
    $("#contactForm")[0].reset();
    if (english) {
        submitMSG(true, "The email was sent correctly!")
    } else {
        submitMSG(true, "El correo fue enviado correctamente.!")
    }
}

function formError(){
    $("#contactForm").removeClass().addClass('shake animated').one('webkitAnimationEnd mozAnimationEnd MSAnimationEnd oanimationend animationend', function(){
        $(this).removeClass();
    });
}

function submitMSG(valid, msg){
    if(valid){
        var msgClasses = "h3 text-left tada animated text-success";
    } else {
        var msgClasses = "h3 text-left text-danger";
    }
    $("#msgSubmit").removeClass().addClass(msgClasses).text(msg);
}